            sql="""
            CREATE FUNCTION timeclock_punch_immutable() RETURNS trigger AS $$
            BEGIN
                IF TG_OP = 'DELETE' THEN
                    RAISE EXCEPTION 'Las marcaciones no se borran: anúlelas con un motivo';
                END IF;
                IF NEW.employee_id IS DISTINCT FROM OLD.employee_id
                   OR NEW."timestamp" IS DISTINCT FROM OLD."timestamp"
                   OR NEW.direction IS DISTINCT FROM OLD.direction
                   OR NEW.source IS DISTINCT FROM OLD.source
                   OR NEW.device_id IS DISTINCT FROM OLD.device_id
                   OR NEW.project_id IS DISTINCT FROM OLD.project_id
                   OR NEW.batch_id IS DISTINCT FROM OLD.batch_id
                   OR NEW.corrects_id IS DISTINCT FROM OLD.corrects_id
                   OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
                   OR (OLD.is_void AND NOT NEW.is_void) THEN
                    RAISE EXCEPTION 'Una marcación no se modifica: corríjala o anúlela';
                END IF;
                RETURN NEW;
            END;
            $$ LANGUAGE plpgsql;
            CREATE TRIGGER timeclock_punch_no_update_delete
                BEFORE UPDATE OR DELETE ON timeclock_punch
                FOR EACH ROW EXECUTE FUNCTION timeclock_punch_immutable();
            """,
